    @classmethod
    def _target_facts(
        cls,
        state: Mapping[str, Any],
        *,
        base_state: Mapping[str, Any],
        window_start: datetime,
        window_end: datetime,
        allowed_review_dates: set[str],
    ) -> dict[str, Any]:
        bookings = [row for row in state.get("bookings", []) if isinstance(row, Mapping)]
        anomalies: list[str] = []
        dynamic = [row for row in bookings if str(row.get("id") or "") not in SEED_BOOKING_IDS]
        invalid_ids = [row.get("id") for row in dynamic if not re.fullmatch(r"OT\d{13}", str(row.get("id") or ""))]
        if invalid_ids:
            anomalies.append(f"invalid dynamic booking ids: {invalid_ids!r}")
        unexpected_types = [row.get("id") for row in dynamic if row.get("type") not in {"hotel", "flight"}]
        if unexpected_types:
            anomalies.append(f"unexpected dynamic booking types: {unexpected_types!r}")

        hotel_candidates = [row for row in dynamic if row.get("type") == "hotel"]
        flight_candidates = [row for row in dynamic if row.get("type") == "flight"]
        hotel_fact = cls._evaluate_dynamic_booking(
            hotel_candidates,
            expected_fingerprint=EXPECTED_HOTEL_FINGERPRINT,
            label="hotel",
            window_start=window_start,
            window_end=window_end,
        )
        flight_fact = cls._evaluate_dynamic_booking(
            flight_candidates,
            expected_fingerprint=EXPECTED_FLIGHT_FINGERPRINT,
            label="flight",
            window_start=window_start,
            window_end=window_end,
        )
        review_fact = cls._evaluate_review(
            state,
            base_state=base_state,
            allowed_review_dates=allowed_review_dates,
        )

        return {
            "flags": (bool(hotel_fact["pass"]), bool(review_fact["pass"]), bool(flight_fact["pass"])),
            "hotel": hotel_fact,
            "review": review_fact,
            "flight": flight_fact,
            "dynamic": dynamic,
            "dynamic_type_counts": {
                "flight": len(flight_candidates),
                "hotel": len(hotel_candidates),
            },
            "anomalies": anomalies,
        }

    @classmethod
    def _evaluate_dynamic_booking(
        cls,
        candidates: Sequence[Mapping[str, Any]],
        *,
        expected_fingerprint: str,
        label: str,
        window_start: datetime,
        window_end: datetime,
    ) -> dict[str, Any]:
        reasons: list[str] = []
        booking = candidates[0] if len(candidates) == 1 else None
        if len(candidates) != 1:
            reasons.append(f"expected exactly one {label} candidate, observed {len(candidates)}")
        timestamp = None
        fingerprint = None
        if isinstance(booking, Mapping):
            booking_id = str(booking.get("id") or "")
            timestamp = cls._try_parse_datetime(booking.get("createdAt"))
            match = re.fullmatch(r"OT(\d{13})", booking_id)
            if not match:
                reasons.append("dynamic order id must be OT followed by exactly 13 digits")
            else:
                id_time = datetime.fromtimestamp(int(match.group(1)) / 1000, tz=timezone.utc)
                if timestamp is None or id_time != timestamp:
                    reasons.append("dynamic order id epoch does not equal createdAt")
            if timestamp is None or not cls._in_window(timestamp, window_start, window_end):
                reasons.append("createdAt is missing or outside the causal window")
            normalized = {key: value for key, value in booking.items() if key not in {"id", "createdAt"}}
            fingerprint = _canonical_json_sha256(normalized)
            if fingerprint != expected_fingerprint:
                reasons.append(f"complete {label} booking fingerprint mismatch")
        return {
            "pass": not reasons,
            "id": booking.get("id") if isinstance(booking, Mapping) else None,
            "timestamp": timestamp,
            "observed": {
                "complete_booking_fingerprint": fingerprint,
                "booking": booking,
            },
            "failure_reason": "; ".join(reasons),
        }

    @classmethod
    def _evaluate_review(
        cls,
        state: Mapping[str, Any],
        *,
        base_state: Mapping[str, Any],
        allowed_review_dates: set[str],
    ) -> dict[str, Any]:
        reasons: list[str] = []
        booking = cls._booking_by_id(state, "OT-SEED-HOTEL-2")
        base_booking = cls._booking_by_id(base_state, "OT-SEED-HOTEL-2")
        observed = booking.get("review") if isinstance(booking, Mapping) else None
        if not isinstance(booking, Mapping) or not isinstance(base_booking, Mapping):
            reasons.append("OT-SEED-HOTEL-2 is missing or duplicated")
        elif not isinstance(observed, Mapping):
            reasons.append("review object is missing")
        else:
            if dict(observed) != REVIEW_EXPECTED:
                reasons.append("review object does not exactly match all expected fields")
            if observed.get("date") not in allowed_review_dates:
                reasons.append("review.date is outside the causal window UTC dates")

            expected_booking = copy.deepcopy(dict(base_booking))
            expected_booking["review"] = copy.deepcopy(REVIEW_EXPECTED)
            expected_item = expected_booking.get("item")
            if not isinstance(expected_item, dict):
                reasons.append("baseline review booking item is invalid")
            else:
                reviews = expected_item.get("reviews")
                if not isinstance(reviews, list):
                    reasons.append("baseline item.reviews is invalid")
                else:
                    expected_item["reviews"] = [copy.deepcopy(REVIEW_EXPECTED), *reviews]
                review_count = expected_item.get("reviewCount")
                if not isinstance(review_count, int):
                    reasons.append("baseline item.reviewCount is invalid")
                else:
                    expected_item["reviewCount"] = review_count + 1
            if _canonical_json_sha256(booking) != _canonical_json_sha256(expected_booking):
                reasons.append("review booking changed outside the exact allowed review fields")

        return {
            "pass": not reasons,
            "observed": observed,
            "failure_reason": "; ".join(reasons),
        }

    @classmethod
    def _evaluate_transaction_history(
        cls,
        commit_states: Sequence[Mapping[str, Any]],
        *,
        base_state: Mapping[str, Any],
        window_start: datetime,
        window_end: datetime,
        allowed_review_dates: set[str],
    ) -> tuple[dict[str, Any], dict[str, Any]]:
        rows: list[dict[str, Any]] = []
        reasons: list[str] = []
        expected_flags = (
            (True, False, False),
            (True, True, False),
            (True, True, True),
        )
        first_commit: list[int | None] = [None, None, None]
        for index, state in enumerate(commit_states, start=1):
            facts = cls._target_facts(
                state,
                base_state=base_state,
                window_start=window_start,
                window_end=window_end,
                allowed_review_dates=allowed_review_dates,
            )
            flags = tuple(bool(value) for value in facts["flags"])
            for position, value in enumerate(flags):
                if value and first_commit[position] is None:
                    first_commit[position] = index
            rows.append(
                {
                    "commit": index,
                    "flags": list(flags),
                    "dynamic_order_ids": [row.get("id") for row in facts["dynamic"]],
                    "anomalies": facts["anomalies"],
                }
            )
            if facts["anomalies"]:
                reasons.append(f"commit {index} contains unexpected target data: {facts['anomalies']}")

        if len(rows) != 3:
            reasons.append(f"expected exactly 3 committed WAL states, observed {len(rows)}")
        if tuple(tuple(row["flags"]) for row in rows) != expected_flags:
            reasons.append("WAL flags are not exact hotel -> review -> flight transitions")
        if first_commit != [1, 2, 3]:
            reasons.append("first committed appearances are not hotel=1, review=2, flight=3")

        evidence = {
            "commit_count": len(rows),
            "first_target_commits": {
                "hotel_booking_exact": first_commit[0],
                "hotel_review_exact": first_commit[1],
                "flight_booking_exact": first_commit[2],
            },
            "expected_flags": [list(row) for row in expected_flags],
            "commits": rows,
            "failure_reasons": reasons,
        }
        return (
            cls._check(
                "wal_transaction_order_exact",
                [30, 36, 70],
                ["source_or_process", "relationship"],
                not reasons,
                RULESET_SPEC["strict_transition_order"],
                evidence,
                "; ".join(reasons),
            ),
            evidence,
        )

    @classmethod
    def _step_coverage(cls, checks: Sequence[Mapping[str, Any]]) -> list[dict[str, Any]]:
        by_name = {str(check.get("name")): check for check in checks}
        chain_for_step = {
            step: chain
            for chain, steps in STEP_GROUPS.items()
            for step in steps
        }
        primary_for_chain = {
            "hotel_booking": "hotel_booking_exact",
            "hotel_review": "hotel_review_exact",
            "flight_booking": "flight_booking_exact",
        }
        direct = {step: [] for step in range(1, 71)}
        for check in checks:
            for step in check.get("steps", []):
                if isinstance(step, int) and step in direct:
                    direct[step].append(str(check.get("name")))
        coverage: list[dict[str, Any]] = []
        for step in range(1, 71):
            chain = chain_for_step[step]
            primary = primary_for_chain[chain]
            names = list(direct[step])
            if primary not in names:
                names.append(primary)
            if "wal_transaction_order_exact" not in names:
                names.append("wal_transaction_order_exact")
            relevant = [by_name[name] for name in names if name in by_name]
            data_step = step in DATA_STEPS
            coverage.append(
                {
                    "step": step,
                    "covered": bool(relevant),
                    "pass": bool(relevant) and all(bool(row.get("pass")) for row in relevant),
                    "data_producing": data_step,
                    "checkpoint_names": names,
                    "dimensions": {
                        "final_object": primary,
                        "content": (
                            f"exact persisted field {DATA_STEP_FIELDS[step]}"
                            if data_step
                            else "covered by the named durable compound chain"
                        ),
                        "source_or_process": "exact committed WAL transition order",
                        "final_ui": "not asserted because the instruction has no final-stay UI requirement",
                    },
                    "mapping_basis": (
                        "direct exact durable evidence and committed transition"
                        if data_step
                        else "required navigation for the named durable chain; no invented event"
                    ),
                }
            )
        return coverage

    @classmethod
    def _resolve_causal_window(
        cls,
        *,
        context: Mapping[str, Any],
        params: Mapping[str, Any],
    ) -> tuple[datetime, datetime, str]:
        run_dir_raw = context.get("run_dir")
        if run_dir_raw:
            args_path = Path(str(run_dir_raw)).expanduser().resolve() / "args.json"
            payload = json.loads(args_path.read_text(encoding="utf-8"))
            start = cls._parse_datetime(payload.get("created_at"), "args.json.created_at")
            end = datetime.now(timezone.utc)
            if end <= start:
                raise ValueError("automatic causal window end must be later than start")
            return start, end, "automatic_run_args_created_at"
        start = cls._parse_datetime(
            params.get("manual_window_start") or MANUAL_WINDOW_START,
            "manual_window_start",
        )
        end = cls._parse_datetime(
            params.get("manual_window_end") or MANUAL_WINDOW_END,
            "manual_window_end",
        )
        if end <= start:
            raise ValueError("manual_window_end must be later than manual_window_start")
        return start, end, "manual_recording_window"

    @classmethod
    def _error_result(cls, message: str) -> EvalResult:
        return EvalResult(
            status=EvalStatus.ERROR,
            message=message,
            metadata={
                "read_only": True,
                "ruleset_sha256": RULESET_SHA256,
                "instruction_sha256": INSTRUCTION_SHA256,
                "ruleset_spec": RULESET_SPEC,
                "checks": [],
                "failures": [],
                "step_coverage": [],
                "coverage_summary": {
                    "instruction_steps": 70,
                    "covered_steps": 0,
                    "passing_steps": 0,
                    "data_steps": list(DATA_STEPS),
                    "uncovered_data_steps": list(DATA_STEPS),
                },
                "observed": {"applications": []},
                "safety": cls._safety_attestation(),
            },
        )


    @staticmethod
    def _check(
        name: str,
        steps: Sequence[int],
        dimensions: Sequence[str],
        passed: bool,
        expected: Any,
        observed: Any,
        failure_reason: str = "",
    ) -> dict[str, Any]:
        return {
            "name": name,
            "steps": list(steps),
            "dimensions": list(dimensions),
            "pass": bool(passed),
            "expected": expected,
            "observed": observed,
            "failure_reason": "" if passed else (failure_reason or f"{name} mismatch"),
        }

    @classmethod
    def _resolve_live_binding(
        cls,
        *,
        udid: str,
        bundle_id: str,
    ) -> tuple[Path, dict[str, Any]]:
        data_container = cls._simctl_container(udid, bundle_id, "data")
        app_container = cls._simctl_container(udid, bundle_id, "app")
        origin_root = data_container / "Library" / "WebKit" / bundle_id / "WebsiteData" / "Default"
        origin_files = sorted(origin_root.glob("*/*/origin"))
        active = [path for path in origin_files if cls._origin_is_exact(path.read_bytes())]
        if len(active) != 1:
            raise RuntimeError(
                f"expected exactly one {EXPECTED_ORIGIN} WebKit origin, observed {len(active)}"
            )
        db_path = active[0].parent / "LocalStorage" / "localstorage.sqlite3"
        if not db_path.is_file():
            raise FileNotFoundError(f"active-origin localStorage database is missing: {db_path}")

        public = app_container / "public"
        hashes = {
            "app_js_sha256": cls._file_sha256(public / "app.js"),
            "seed_data_sha256": cls._file_sha256(public / "seed-data.js"),
            "flight_data_sha256": cls._file_sha256(public / "flights" / "2026-06-12.json"),
        }
        wanted = {
            "app_js_sha256": EXPECTED_APP_JS_SHA256,
            "seed_data_sha256": EXPECTED_SEED_DATA_SHA256,
            "flight_data_sha256": EXPECTED_FLIGHT_DATA_SHA256,
        }
        failures = [f"{key} mismatch" for key in wanted if hashes[key] != wanted[key]]
        if failures:
            raise RuntimeError("OpenTrip application/data binding mismatch: " + "; ".join(failures))
        application = {
            "bundle_id": bundle_id,
            "origin": EXPECTED_ORIGIN,
            "local_state_key": LOCAL_STATE_KEY,
            "app_container": str(app_container),
            "data_container": str(data_container),
            **hashes,
        }
        return db_path, {
            "pass": not failures,
            "failure_reason": "; ".join(failures),
            "bundle_id": bundle_id,
            "origin": EXPECTED_ORIGIN,
            "active_origin_count": 1,
            "origin_file_count": len(origin_files),
            "database_path": str(db_path),
            "applications": [application],
        }

    @staticmethod
    def _simctl_container(udid: str, bundle_id: str, kind: str) -> Path:
        proc = subprocess.run(
            ["xcrun", "simctl", "get_app_container", udid, bundle_id, kind],
            capture_output=True,
            text=True,
            timeout=30,
        )
        if proc.returncode != 0:
            raise RuntimeError(f"simctl get_app_container {kind} failed: {proc.stderr.strip()}")
        from platforms.ios.runtime_env.simulator_manager import remap_simulator_container_path
        path = remap_simulator_container_path(proc.stdout.strip(), udid)
        if not path.exists():
            raise FileNotFoundError(f"simctl {kind} container does not exist: {path}")
        return path

    @staticmethod
    def _origin_is_exact(payload: bytes) -> bool:
        def component(value: bytes) -> bytes:
            return struct.pack("<I", len(value)) + b"\x01" + value

        record = component(b"capacitor") + component(b"localhost") + b"\x00"
        return payload == record + record

    @classmethod
    def _read_state_snapshot_and_history(
        cls,
        *,
        db_path: Path,
        local_state_key: str,
    ) -> tuple[dict[str, Any], dict[str, Any], list[dict[str, Any]], dict[str, Any]]:
        if not db_path.is_file():
            raise FileNotFoundError(f"localStorage database not found: {db_path}")
        with tempfile.TemporaryDirectory(prefix="opentrip-234497-verifier-") as temporary:
            snapshot = Path(temporary) / "localstorage.sqlite3"
            copied_sidecars, stable_stats = cls._copy_consistent_sqlite_set(db_path, snapshot)
            final_state = cls._read_local_state(snapshot, local_state_key, include_wal=True)
            base_state = cls._read_local_state(snapshot, local_state_key, include_wal=False)
            wal_path = Path(f"{snapshot}-wal")
            commit_states = (
                cls._replay_wal_commits(snapshot, wal_path, local_state_key)
                if wal_path.is_file() and wal_path.stat().st_size > 32
                else []
            )
            evidence = {
                "quick_check": "ok",
                "snapshot_read": True,
                "base_database_read_immutable": True,
                "copied_sidecars": copied_sidecars,
                "copy_source_stable": True,
                "source_stats": stable_stats,
                "local_state_key": local_state_key,
                "source_database_sha256": cls._file_sha256(db_path),
                "wal_commit_count": len(commit_states),
                "host_temp_only": True,
            }
        return final_state, base_state, commit_states, evidence

    @classmethod
    def _copy_consistent_sqlite_set(
        cls,
        source: Path,
        target: Path,
    ) -> tuple[list[str], dict[str, dict[str, int]]]:
        paths = [source] + [
            path for suffix in ("-wal", "-shm")
            if (path := Path(f"{source}{suffix}")).is_file()
        ]
        for _attempt in range(3):
            before = {str(path): cls._stat_signature(path) for path in paths}
            shutil.copy2(source, target)
            copied: list[str] = []
            for suffix in ("-wal", "-shm"):
                source_sidecar = Path(f"{source}{suffix}")
                target_sidecar = Path(f"{target}{suffix}")
                if source_sidecar.is_file():
                    shutil.copy2(source_sidecar, target_sidecar)
                    copied.append(suffix)
                elif target_sidecar.exists():
                    target_sidecar.unlink()
            after = {str(path): cls._stat_signature(path) for path in paths if path.exists()}
            if before == after:
                return copied, before
        raise RuntimeError("SQLite source changed during three read-only snapshot attempts")

    @staticmethod
    def _stat_signature(path: Path) -> dict[str, int]:
        stat = path.stat()
        return {"size": stat.st_size, "mtime_ns": stat.st_mtime_ns, "inode": stat.st_ino}

    @classmethod
    def _read_local_state(
        cls,
        db_path: Path,
        key: str,
        *,
        include_wal: bool,
    ) -> dict[str, Any]:
        query = f"file:{db_path}?mode=ro" + ("" if include_wal else "&immutable=1")
        conn = sqlite3.connect(query, uri=True)
        try:
            quick = conn.execute("PRAGMA quick_check").fetchall()
            if quick != [("ok",)]:
                raise RuntimeError(f"SQLite quick_check failed: {quick!r}")
            rows = conn.execute("SELECT value FROM ItemTable WHERE key = ?", (key,)).fetchall()
        finally:
            conn.close()
        if len(rows) != 1:
            raise RuntimeError(f"expected one localStorage row for {key!r}, observed {len(rows)}")
        return cls._decode_state(rows[0][0])

    @classmethod
    def _replay_wal_commits(
        cls,
        base_db: Path,
        wal_path: Path,
        key: str,
    ) -> list[dict[str, Any]]:
        payload = wal_path.read_bytes()
        if len(payload) < 32:
            return []
        magic, version, page_size, _sequence, salt1, salt2, header_c1, header_c2 = struct.unpack(
            ">8I", payload[:32]
        )
        if magic not in {0x377F0682, 0x377F0683}:
            raise RuntimeError(f"invalid WAL magic: {magic:#x}")
        if version != 3007000:
            raise RuntimeError(f"unsupported WAL version: {version}")
        if page_size == 1:
            page_size = 65536
        if page_size < 512 or page_size > 65536 or page_size & (page_size - 1):
            raise RuntimeError(f"invalid WAL page size: {page_size}")
        checksum_byte_order = "little" if magic == 0x377F0682 else "big"
        calculated_header = cls._wal_checksum(
            payload[:24],
            byte_order=checksum_byte_order,
        )
        if calculated_header != (header_c1, header_c2):
            raise RuntimeError("WAL header checksum mismatch")
        frame_size = 24 + page_size
        if (len(payload) - 32) % frame_size:
            raise RuntimeError("WAL contains a partial frame")

        replay = base_db.parent / "wal-replay.sqlite3"
        shutil.copy2(base_db, replay)
        states: list[dict[str, Any]] = []
        rolling_checksum = calculated_header
        with replay.open("r+b") as handle:
            for offset in range(32, len(payload), frame_size):
                page_no, db_size, frame_salt1, frame_salt2, frame_c1, frame_c2 = struct.unpack(
                    ">6I", payload[offset : offset + 24]
                )
                if page_no <= 0:
                    raise RuntimeError(f"invalid WAL page number at offset {offset}")
                if (frame_salt1, frame_salt2) != (salt1, salt2):
                    raise RuntimeError(f"WAL salt mismatch at offset {offset}")
                page = payload[offset + 24 : offset + frame_size]
                rolling_checksum = cls._wal_checksum(
                    payload[offset : offset + 8] + page,
                    byte_order=checksum_byte_order,
                    seed=rolling_checksum,
                )
                if rolling_checksum != (frame_c1, frame_c2):
                    raise RuntimeError(f"WAL frame checksum mismatch at offset {offset}")
                handle.seek((page_no - 1) * page_size)
                handle.write(page)
                if db_size:
                    handle.truncate(db_size * page_size)
                    handle.flush()
                    states.append(cls._read_local_state(replay, key, include_wal=False))
        return states

    @staticmethod
    def _wal_checksum(
        payload: bytes,
        *,
        byte_order: str,
        seed: tuple[int, int] = (0, 0),
    ) -> tuple[int, int]:
        """Return SQLite's rolling WAL checksum for an 8-byte-aligned payload."""

        if len(payload) % 8:
            raise RuntimeError("WAL checksum input is not aligned to eight bytes")
        if byte_order not in {"little", "big"}:
            raise ValueError(f"unsupported WAL checksum byte order: {byte_order}")
        s0, s1 = seed
        for offset in range(0, len(payload), 8):
            word0 = int.from_bytes(payload[offset : offset + 4], byte_order)
            word1 = int.from_bytes(payload[offset + 4 : offset + 8], byte_order)
            s0 = (s0 + word0 + s1) & 0xFFFFFFFF
            s1 = (s1 + word1 + s0) & 0xFFFFFFFF
        return s0, s1

    @staticmethod
    def _decode_state(raw: Any) -> dict[str, Any]:
        if isinstance(raw, memoryview):
            raw = bytes(raw)
        if isinstance(raw, bytes):
            text = raw.decode("utf-16-le").rstrip("\x00")
        elif isinstance(raw, str):
            text = raw.rstrip("\x00")
        else:
            raise TypeError(f"unsupported localStorage value type: {type(raw)!r}")
        state = json.loads(text)
        if not isinstance(state, dict):
            raise TypeError("OpenTrip local state must decode to an object")
        return state

    @staticmethod
    def _safety_attestation() -> dict[str, bool]:
        return {
            "read_only": True,
            "sqlite_snapshot_to_host_temp": True,
            "simulator_reset": False,
            "simulator_restore": False,
            "initializer": False,
            "gui_action": False,
            "app_launch": False,
            "appium": False,
            "simulator_boot": False,
            "simulator_shutdown": False,
            "app_or_simulator_data_write": False,
        }

    @classmethod
    def _parse_datetime(cls, value: Any, label: str) -> datetime:
        parsed = cls._try_parse_datetime(value)
        if parsed is None:
            raise ValueError(f"{label} must be a timezone-aware ISO-8601 timestamp")
        return parsed

    @staticmethod
    def _try_parse_datetime(value: Any) -> datetime | None:
        text = str(value or "").strip()
        if not text:
            return None
        try:
            parsed = datetime.fromisoformat(text.replace("Z", "+00:00"))
        except ValueError:
            return None
        if parsed.tzinfo is None:
            return None
        return parsed.astimezone(timezone.utc)

    @staticmethod
    def _in_window(value: datetime, start: datetime, end: datetime) -> bool:
        return start.astimezone(timezone.utc) <= value <= end.astimezone(timezone.utc)

    @staticmethod
    def _utc_dates_in_window(start: datetime, end: datetime) -> set[str]:
        start_date = start.astimezone(timezone.utc).date()
        end_date = end.astimezone(timezone.utc).date()
        return {
            datetime.fromordinal(ordinal).date().isoformat()
            for ordinal in range(start_date.toordinal(), end_date.toordinal() + 1)
        }

    @staticmethod
    def _booking_ids(state: Mapping[str, Any]) -> list[str]:
        return [
            str(row.get("id") or "")
            for row in state.get("bookings", [])
            if isinstance(row, Mapping)
        ]

    @staticmethod
    def _booking_by_id(state: Mapping[str, Any], booking_id: str) -> Mapping[str, Any] | None:
        rows = [
            row
            for row in state.get("bookings", [])
            if isinstance(row, Mapping) and row.get("id") == booking_id
        ]
        return rows[0] if len(rows) == 1 else None

    @staticmethod
    def _iso(value: datetime | None) -> str | None:
        return value.isoformat() if value is not None else None

    @staticmethod
    def _file_sha256(path: Path) -> str:
        if not path.is_file():
            raise FileNotFoundError(path)
        digest = hashlib.sha256()
        with path.open("rb") as handle:
            for chunk in iter(lambda: handle.read(1024 * 1024), b""):
                digest.update(chunk)
        return digest.hexdigest()


